// Mock backend responses for MSW, in the render contract (shared/src/contract.ts):
// the backend has already positioned everything; the frontend only plots it.
//
// `replica` is the real 8 August 2026 issue, "(196) Capital Kranti_08
// august.pdf", every element at its true printed position -- generated by
// scripts/mock_backend/from_source.py (never edit the JSON by hand). Plotted
// correctly, it should look like the original paper.
//
// `stress` is synthetic on purpose: a page size that isn't (196)'s, text that
// runs past its box, an element hanging off the page, a missing image, a font
// URL that doesn't exist, deliberate overlaps, 6 pages. Plotting it must not
// crash, and every planted problem must come back as a warning.

import type { Element, IssueRender } from "@ck/shared/contract";
import { plainText } from "@ck/shared/plot";
import replicaJson from "./issue-2026-08-08.json";

const REPLICA = replicaJson as IssueRender;

function firstPages(issue: IssueRender, n: number): IssueRender {
  return { ...issue, pages: issue.pages.filter((p) => p.number <= n) };
}

// ---- stress ----
const PT = 300 / 72; // pt -> contract px at 300 DPI
const W = 800 * PT; // a tabloid-ish page, deliberately not (196)'s size
const H = 1100 * PT;
// all of page 1's text joined -- far more than any one stress box can hold
const LONG = REPLICA.pages[0].elements
  .flatMap((e) => (e.kind === "text" ? [plainText(e)] : []))
  .join("\n\n");

function stressPage(n: number): Element[] {
  const id = (s: string) => `s${n}-${s}`;
  return [
    { id: id("bg"), kind: "rect", x: 0, y: 0, width: W, height: 60 * PT, fill: "#2e3092" },
    { id: id("folio"), kind: "text", x: 20 * PT, y: 12 * PT, width: 300 * PT, height: 36 * PT,
      text: `કેપિટલ ક્રાંતિ · પાનું ${n}`, font: "hind-bold", size: 22 * PT, lineHeight: 36 * PT,
      color: "#ffffff", vAlign: "middle" },
    { id: id("rule"), kind: "line", x1: 20 * PT, y1: 70 * PT, x2: W - 20 * PT, y2: 70 * PT,
      color: "#231f20", width: 1.5 * PT, dash: [6 * PT, 3 * PT] },
    // headline sized and positioned by "the backend"
    { id: id("head"), kind: "text", articleId: `s${n}-lead`, x: 20 * PT, y: 84 * PT, width: 760 * PT, height: 60 * PT,
      text: "બેકએન્ડે ગોઠવેલું શીર્ષક પૂરી પહોળાઈમાં", font: "hind-bold", size: 40 * PT, lineHeight: 48 * PT, align: "center" },
    // body that fits
    { id: id("fits"), kind: "text", articleId: `s${n}-lead`, x: 20 * PT, y: 150 * PT, width: 370 * PT, height: 700 * PT,
      text: LONG.slice(0, 700), font: "hind-regular", size: 12 * PT, lineHeight: 15.6 * PT, align: "justify",
      indent: 10 * PT, hScale: 0.95 },
    // body far too long for its box -> text-overflow warning, text stays visible
    { id: id("overflow"), kind: "text", articleId: `s${n}-lead`, x: 410 * PT, y: 150 * PT, width: 370 * PT, height: 200 * PT,
      text: LONG, font: "hind-regular", size: 12 * PT, lineHeight: 15.6 * PT, align: "justify" },
    // photo that exists, and one that doesn't -> image-failed warning
    { id: id("photo"), kind: "image", articleId: `s${n}-lead`, x: 410 * PT, y: 700 * PT, width: 370 * PT, height: 200 * PT,
      url: "/replica/handloom-photo0.jpg", fit: "cover" },
    { id: id("missing"), kind: "image", x: 20 * PT, y: 870 * PT, width: 200 * PT, height: 120 * PT,
      url: "/replica/does-not-exist.jpg", fit: "contain" },
    // overlap on purpose: a translucent box drawn over the photo (later = on top)
    { id: id("overlay"), kind: "rect", x: 430 * PT, y: 720 * PT, width: 120 * PT, height: 40 * PT,
      fill: "rgba(255,255,255,0.8)", stroke: "#e2001a", strokeWidth: 2 * PT, radius: 6 * PT },
    { id: id("overlay-text"), kind: "text", x: 436 * PT, y: 724 * PT, width: 110 * PT, height: 32 * PT,
      text: "ફોટો", font: "hind-bold", size: 18 * PT, lineHeight: 32 * PT, color: "#e2001a", align: "center" },
    // hangs off the right edge -> off-page warning
    { id: id("offpage"), kind: "rect", x: W - 60 * PT, y: 1000 * PT, width: 120 * PT, height: 50 * PT, fill: "#ffd600" },
    // uses a font whose URL doesn't exist -> font-failed warning (falls back to a system face)
    { id: id("badfont"), kind: "text", x: 240 * PT, y: 900 * PT, width: 160 * PT, height: 60 * PT,
      text: "ખોટો ફોન્ટ", font: "missing-font", size: 20 * PT, lineHeight: 26 * PT },
  ];
}

const STRESS: IssueRender = {
  issueDate: "2026-08-09",
  issueNumber: 197,
  dpi: 300,
  fonts: [...REPLICA.fonts, { id: "missing-font", url: "/fonts/does-not-exist.ttf" }],
  pages: [1, 2, 3, 4, 5, 6].map((n) => ({ number: n, width: W, height: H, background: "#fffdf7", elements: stressPage(n) })),
};

export const FIXTURES = {
  replica: REPLICA,
  onePage: firstPages(REPLICA, 1),
  twoPage: firstPages(REPLICA, 2),
  stress: STRESS,
} as const;

/** Which issue the mock backend serves -- override with the MOCK_FIXTURE env
 * var (replica | one | two | stress). Defaults to the real 8 August replica. */
export function selectFixture(): IssueRender {
  const key = process.env.MOCK_FIXTURE?.trim().toLowerCase();
  if (key === "one") return FIXTURES.onePage;
  if (key === "two") return FIXTURES.twoPage;
  if (key === "stress") return FIXTURES.stress;
  return FIXTURES.replica;
}
